(function(window,document){'use strict';var MEDIA_CLASS='o2-lazyload';var BG_CLASS='o2-lazyload-bg';var SELECTOR='.'+MEDIA_CLASS+',.'+BG_CLASS;var cssRules=window.o2rLazyBg||[];var pendingVars=typeof WeakMap==='function'?new WeakMap():null;var observer=null;function swap(el,name){var value=el.getAttribute('data-'+name);if(value!==null){el.setAttribute(name,value);el.removeAttribute('data-'+name)}}
function setVars(el,vars){for(var name in vars){if(Object.prototype.hasOwnProperty.call(vars,name)){el.style.setProperty(name,'url("'+String(vars[name]).replace(/"/g,'%22')+'")')}}}
function load(el){if(el.classList.contains(MEDIA_CLASS)){var parent=el.parentNode;if(parent&&parent.nodeName==='PICTURE'){Array.prototype.forEach.call(parent.querySelectorAll('source'),function(source){swap(source,'srcset')})}
swap(el,'srcset');swap(el,'src');el.classList.remove(MEDIA_CLASS)}
if(el.classList.contains(BG_CLASS)){try{setVars(el,JSON.parse(el.getAttribute('data-o2r-bg')||'{}'))}catch(error){}
el.removeAttribute('data-o2r-bg');el.classList.remove(BG_CLASS)}
if(pendingVars&&pendingVars.has(el)){setVars(el,pendingVars.get(el));pendingVars.delete(el)}}
function watch(el){if(observer){observer.observe(el)}else{load(el)}}
function watchCss(root){if(!pendingVars||!cssRules.length){return}
cssRules.forEach(function(rule){var elements=[];try{if(root.matches&&root.matches(rule.s)){elements.push(root)}
if(root.querySelectorAll){elements=elements.concat(Array.prototype.slice.call(root.querySelectorAll(rule.s)))}}catch(error){return}
elements.forEach(function(el){var vars=pendingVars.get(el)||{};for(var name in rule.v){if(Object.prototype.hasOwnProperty.call(rule.v,name)){vars[name]=rule.v[name]}}
pendingVars.set(el,vars);watch(el)})})}
function observe(root){if(root.classList&&(root.classList.contains(MEDIA_CLASS)||root.classList.contains(BG_CLASS))){watch(root)}
if(root.querySelectorAll){Array.prototype.forEach.call(root.querySelectorAll(SELECTOR),watch)}
watchCss(root)}
function playYoutube(event){var facade=event.target&&event.target.closest?event.target.closest('.o2r-youtube'):null;if(!facade||!facade.getAttribute('data-o2r-iframe')){return}
event.preventDefault();var holder=document.createElement('div');holder.innerHTML=facade.getAttribute('data-o2r-iframe');var iframe=holder.querySelector('iframe');if(!iframe){return}
if(!iframe.getAttribute('width')&&!iframe.style.width){iframe.style.width='100%';iframe.style.height='100%';iframe.style.aspectRatio=facade.style.aspectRatio||'16/9'}
facade.parentNode.replaceChild(iframe,facade)}
document.addEventListener('click',playYoutube);if('IntersectionObserver' in window){observer=new IntersectionObserver(function(entries){for(var i=0;i<entries.length;i++){if(entries[i].isIntersecting){observer.unobserve(entries[i].target);load(entries[i].target)}}},{rootMargin:(window.o2rLazyMargin||300)+'px 0px'})}
observe(document);if('MutationObserver' in window){new MutationObserver(function(mutations){for(var i=0;i<mutations.length;i++){for(var j=0;j<mutations[i].addedNodes.length;j++){if(mutations[i].addedNodes[j].nodeType===1){observe(mutations[i].addedNodes[j])}}}}).observe(document.documentElement,{childList:!0,subtree:!0})}})(window,document)
